import json

grid = [
    [0, 0, 6, 0, 0, 1, 5, 5, 5, 0, 0],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 5],
    [0, 0, 0, 0, 0, 1, 5, 5, 5, 5, 0],
    [0, 0, 0, 0, 6, 1, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 0]
]

# For each position (row, col), pick the non-1 value closest to the center
# Or pick max of left and right
output = []
for r in range(5):
    new_row = []
    for c in range(11):
        left = grid[r][c]
        right = grid[r][10-c]
        if left == 1:
            new_row.append(1)
        elif right == 1:
            new_row.append(1)
        elif left == 0 and right == 0:
            new_row.append(0)
        elif left == 0:
            new_row.append(right)
        elif right == 0:
            new_row.append(left)
        else:
            # Both non-zero (not 1)
            if left == right:
                new_row.append(left)
            elif left + right == 11:  # One is 5, one is 6
                new_row.append(1)  # Use 1 as conflict
            else:
                new_row.append(max(left, right))
    output.append(new_row)

print("Pick non-1 non-zero from either side:")
for row in output:
    print(' '.join(str(x) for x in row))

print(json.dumps({'action': 'submit', 'grid': output}))
